import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/EmbeddedLang.html","title":"EmbeddedLang","lang":"en-US","frontmatter":{},"git":{"createdTime":1734955547000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":4}]},"readingTime":{"minutes":0.62,"words":185},"filePathRelative":"EmbeddedLang.md"}`),a={name:`EmbeddedLang.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="embeddedlang" tabindex="-1"><a class="header-anchor" href="#embeddedlang"><span>EmbeddedLang</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a></p><p>Embedで使える手頃な言語がたまに欲しくなるのでそのメモを。</p><h2 id="android" tabindex="-1"><a class="header-anchor" href="#android"><span>Android</span></a></h2><ul><li><a href="./Starlark.html">Starlark</a></li><li><a href="https://beanshell.github.io/home.html" target="_blank" rel="noopener noreferrer">BeanShell - Lightweight Scripting for Java</a><ul><li><a href="https://github.com/zhanghai/BeeShell?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">zhanghai/BeeShell: Java REPL on Android with BeanShell</a></li><li>yeildが出来なさそう、classはAndroidでは使えない疑惑もあり</li></ul></li><li><a href="./Rhino.html">Rhino</a> <a href="./JavaScript.html">JavaScript</a>の<a href="./Java.html">Java</a>実装</li></ul><h2 id="ネイティブ系" tabindex="-1"><a class="header-anchor" href="#ネイティブ系"><span>ネイティブ系</span></a></h2><p><a href="https://github.com/dbohdan/embedded-scripting-languages?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">dbohdan/embedded-scripting-languages: A list of embedded scripting languages</a>に結構たくさんのリストがあって、それを見ていって思ったもの。</p><h3 id="chatscript" tabindex="-1"><a class="header-anchor" href="#chatscript"><span>ChatScript</span></a></h3><p><a href="https://chaiscript.com/index.html" target="_blank" rel="noopener noreferrer">ChaiScript - Easy to use scripting for C++.</a></p><p>ヘッダオンリーで使いやすそうで、言語も割と好み。</p><h3 id="pocketlang" tabindex="-1"><a class="header-anchor" href="#pocketlang"><span>pocketlang</span></a></h3><p><a href="https://github.com/ThakeeNathees/pocketlang?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">ThakeeNathees/pocketlang: A lightweight, fast embeddable scripting language.</a></p><p>言語は割と好み。サイズも小さそうだがちょっとファイルが多いか。</p><h3 id="pocketpy" tabindex="-1"><a class="header-anchor" href="#pocketpy"><span>pocketpy</span></a></h3><p><a href="https://github.com/pocketpy/pocketpy?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">pocketpy/pocketpy: Portable Python 3.x Interpreter in Modern C</a></p><p>Pythonのサブセットっぽい。ヘッダと.c一つで組み込めるので楽そう。どのくらい動くのか良く分からないが、結構いろいろ動きそうに見える。 Pythonのサブセットは学習コストが無いからいいかもしれないなぁ。Python嫌いじゃないし。</p><h3 id="umka" tabindex="-1"><a class="header-anchor" href="#umka"><span>umka</span></a></h3><p><a href="https://github.com/vtereshkov/umka-lang/tree/master" target="_blank" rel="noopener noreferrer">vtereshkov/umka-lang: Umka: a statically typed embeddable scripting language</a></p><p>golangっぽいがちょっと好み。ただビルドや組み込みのしやすさが良く分からなかった。</p><h3 id="wern" tabindex="-1"><a class="header-anchor" href="#wern"><span>Wern</span></a></h3><p><a href="https://github.com/wren-lang/wren" target="_blank" rel="noopener noreferrer">wren-lang/wren: The Wren Programming Language. Wren is a small, fast, class-based concurrent scripting language.</a></p><p>言語は割と好み。小さくて組み込みやすそうで、ドキュメントがしっかりしている。良いかも。</p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};